	if (!get_variable_scratch(_scratch, _variables, name.begin, name.end, &var))
		return error_oom();

	if (!var)
		return error("Unknown variable: variable set does not contain the given name");

	_lexer.next();

	return alloc_node(ast_variable, var->type(), var);

